INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('c22c0055-acc4-44db-b724-1d11a5a2622c', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-CDO-3005', 'Tracline Yoga Mat', 'tracline-yoga-mat', 'A 5mm natural rubber mat with a textured surface that actually grips through a sweaty flow.', 'Most yoga mats get slippery right when you need grip most — twenty minutes into a hot flow. Tracline''s natural rubber base and textured top layer are built specifically to hold traction as you sweat, not despite it.
